{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Labetalol absolute oral bioavailability was 29.9 ± 1.7% in normal subjects after 200 mg oral vs 0.5 mg/kg IV, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Cilomilast absolute oral bioavailability was 96% (range 92–102%) in fasted healthy male volunteers after 10 mg oral solution vs IV infusion, strongly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Isradipine systemic availability was 17% in healthy volunteers after 5 mg oral vs IV, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence molecules support F ≥ 20%, with direct absolute bioavailability values from healthy subjects (e.g., 29.9%, 96%, 49%, 38%, 22–55%); one high-transfer molecule (isradipine) consistently shows ~17% systemic availability. The preponderance supports high bioavailability.",
  "evidence_gaps": [
    "One high-transfer molecule (isradipine) consistently reports low systemic availability (~16–19%) in healthy volunteers, conflicting with the otherwise high pattern.",
    "Some positive records come from altered populations (cirrhosis, elderly) or qualitative 'complete bioavailability' reports, but direct healthy-subject absolute measurements dominate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

